enum QuotaBarIndex {
    kFiveHourBar,
    kWeeklyBar,
    kFableWeeklyBar,
    kExtraUsageBar,
    // Antigravity only: shared pool of the non-Gemini models ("Other").
    kOtherBar,
    kOtherWeeklyBar,
    kQuotaBarCount,
};

// Antigravity can pick up to three of its four quotas as arcs (the tile has three), and so can
// Claude once its Fable weekly arc is checked.
static constexpr int kMaxTileArcs = 3;

struct AccountConfig {
    std::wstring provider;  // "anthropic", "openai", "antigravity" or "copilot".
    std::wstring label;
    // GitHub login selection; never part of AccountIdentityHash and never stores credentials.
    std::wstring copilotLogin;
    std::array<bool, kQuotaBarCount> showBars{true, true, false, false, false, false};
    // OpenAI only: user-chosen credits ceiling that turns the prepaid balance into a
    // used-percent bar in the extra-usage slot. 0 disables the bar.
    int creditsMax = 0;
    bool hidden = false;  // Runtime show/hide toggle (right-click menu), persisted in mod storage.
    // Uses the Claude Code / Codex sign-in (read-only access token) instead of the mod's own
    // session. Anthropic and OpenAI only.
    bool useCliLogin = false;
    // Per-account visibility of additional data; does not change alerts or identity.
    bool showOpenAiExtraLimits = false;
    bool showFableWeekly = true;
    // Anthropic only: Fable weekly as a tile arc; requires showFableWeekly (ShowsTileArc).
    bool showFableWeeklyArc = false;
    bool showOtherModelsUsage = true;
    bool showModelLimits = true;
    bool showAdditionalGeminiBuckets = true;
    // Tile icon (presentation only; not part of the account identity).
    // 0 = provider logo, 1 = text/symbol, 2 = custom SVG (iconAsset).
    int iconKind = 0;
    std::wstring iconText;
    // SHA-256 (64 lowercase hex) of the imported SVG; the files live in icons\ in the mod's
    // storage. Only meaningful with iconKind == 2.
    std::wstring iconAsset;

    bool operator==(const AccountConfig&) const = default;
};

// Tile position: a subset of Taskbar Fluent Media Player's "Media player position" without the
// overlay positions or most of the ones that land in the same spot. Taskbar* positions float over
// the taskbar root next to a button; Tray* positions add a column to the tray. The id is saved in
// settings_v1 and matches the media player mod's id.
enum class TilePosition {
    TaskbarLeftOfStart,
    TaskbarRightOfStart,
    TaskbarRightOfSearch,
    TaskbarRightOfTaskView,
    TaskbarLeftOfWidgets,
    TaskbarRightOfWidgets,
    TrayFarLeft,
    TrayRightOfHiddenIcons,
    TrayLeftOfNetwork,
    TrayLeftOfClock,
    TrayFarRight,
    Count,
};

struct TilePositionInfo {
    PCWSTR id;
    Str label;
};

static const TilePositionInfo kTilePositions[(int)TilePosition::Count] = {
    {L"taskbar_left_start", Str::TilePosTaskbarLeftOfStart},
    {L"taskbar_right_start", Str::TilePosTaskbarRightOfStart},
    {L"taskbar_after_search_right", Str::TilePosTaskbarRightOfSearch},
    {L"taskbar_after_taskview_right", Str::TilePosTaskbarRightOfTaskView},
    {L"taskbar_after_widgets_left", Str::TilePosTaskbarLeftOfWidgets},
    {L"taskbar_after_widgets_right", Str::TilePosTaskbarRightOfWidgets},
    {L"tray_left", Str::TilePosTrayFarLeft},
    {L"tray_hidden_icons_right", Str::TilePosTrayRightOfHiddenIcons},
    {L"tray_before_omni_left", Str::TilePosTrayLeftOfNetwork},
    {L"tray_before_clock", Str::TilePosTrayLeftOfClock},
    {L"tray_right", Str::TilePosTrayFarRight},
};

static bool IsTaskbarTilePosition(TilePosition position) {
    return position <= TilePosition::TaskbarRightOfWidgets;
}

static TilePosition TilePositionFromId(std::wstring_view id) {
    for (int i = 0; i < (int)TilePosition::Count; i++) {
        if (id == kTilePositions[i].id) return (TilePosition)i;
    }
    return TilePosition::TrayFarLeft;
}

