struct SettingsRow {
    HWND label = nullptr;
    HWND control = nullptr;
    HWND slider = nullptr;
    HWND spin = nullptr;
    // Colors: `colorPicker` is the swatch button of the threshold rows (on the base row and the
    // pace marker row the swatch is `control`); `colorReset` is the icon button.
    HWND colorPicker = nullptr;
    HWND colorReset = nullptr;
    COLORREF previewColor = RGB(128, 128, 128);
    int minimum = 0;
    int maximum = 0;
    // Fluent card: help text under the label (a STATIC on rows with a control; on toggle rows the
    // button paints it itself).
    HWND caption = nullptr;
    std::wstring captionText;
    int groupRows = 0;      // Expander header: number of subrows that follow it.
    bool grouped = false;   // Row inside a group card.
    int parentId = 0;       // Dependent subrow, inside the card of the given control.
    bool hidden = false;    // Takes no part in layout, tab order or page captures.
    bool dependentGroup = false;  // Expander header (chevron in `extra`).
    bool expanded = false;  // Local expansion state; never saved in the settings.
    bool applicable = false;  // Last applicability seen: detects the change that auto-expands.
    bool enabled = true;    // Disabled label painted without the classic embossed text.
    bool visible = false;   // On the current subpage (to paint its card).
    HWND extra = nullptr;        // Second button; in an expander it is the chevron on the right.
    // Content without a card (About): full-width text or a left-aligned button, separated from the
    // previous row by `plainGap` DIP.
    bool plain = false;
    // Further card-less buttons on the same line as `control`, with equal gaps (About links).
    std::array<HWND, 2> inlineButtons{};
    bool headerIcon = false;    // Header with the logo (40 DIP HeaderIcon).
    int plainGap = 0;
    // Section header (Body Strong over the background, as in Windows Settings): a `plain` row whose
    // control is a full-width STATIC.
    bool sectionHeader = false;
    RECT card{};
    RECT inputFrame{};
};

// A single list so a subrow's accessories are hidden too.
static std::array<HWND, 10> SettingsRowWindows(const SettingsRow& row) {
    return {row.label, row.caption, row.control, row.slider, row.spin,
            row.colorPicker, row.colorReset, row.extra, row.inlineButtons[0],
            row.inlineButtons[1]};
}

// GDI palette of the settings window and the account editor. It comes from GetUiPalette (WinUI
// tokens, system accent, high contrast); GDI has no transparency, so tokens with alpha are stored
// as UiColor and blended over the surface they are painted on.
struct NativeTheme {
    bool dark = false;
    bool highContrast = false;
    UiColor text{}, textSecondary{}, textDisabled{};
    UiColor control{}, controlHover{}, controlPressed{}, controlDisabled{}, controlStroke{};
    UiColor strongStroke{}, strongStrokeDisabled{}, altFill{}, altFillHover{}, knobOff{};
    UiColor subtleHover{}, subtlePressed{};
    UiColor accent{}, accentHover{}, accentPressed{}, accentDisabled{};
    UiColor accentText{}, accentTextDisabled{};
    UiColor linkText{}, linkTextHover{}, linkTextPressed{};  // HyperlinkButton (see UiPalette).
    UiColor cardFill{}, cardFillHover{}, cardSecondaryFill{}, cardStroke{}, dividerStroke{}, focusStroke{};
    // Elevation border (ControlStrokeColorSecondary and the strokes over accent), inner focus
    // stroke, subtle navigation and list fills, and the dropdown stroke.
    UiColor controlStrokeSecondary{}, accentStroke{}, accentStrokeSecondary{}, focusInner{};
    UiColor subtleSecondary{}, subtleTertiary{}, popupStroke{};
    // SystemFillColorAttention/Success/Caution/Critical and their Background tokens.
    std::array<UiColor, 4> statusFill{}, statusBackground{};
    UiColor statusGlyph{};
    // Severity colors for text on a surface (inline validation): window text in high contrast.
    std::array<UiColor, 4> statusText{};
    // Tint of the dropdown's Acrylic (window accent policy, not a GDI fill): keeps the hue of what
    // is behind with the luminosity of the WinUI color.
    UiColor popupTint{};
    // Colors already blended over their usual surface.
    COLORREF back = 0, card = 0, cardHover = 0, cardBorder = 0, footer = 0, divider = 0;
    COLORREF textOnCard = 0, secondaryOnCard = 0, disabledOnCard = 0;
    COLORREF input = 0, inputDisabled = 0, inputBorder = 0;
    COLORREF popup = 0;  // Dropdown background (AcrylicInAppFillColorDefault without acrylic).
    COLORREF cardSecondary = 0;
    HBRUSH cardSecondaryBrush = nullptr;
    HBRUSH backBrush = nullptr, cardBrush = nullptr, footerBrush = nullptr;
    HBRUSH inputBrush = nullptr, inputDisabledBrush = nullptr, popupBrush = nullptr;
    HFONT body = nullptr, bodyStrong = nullptr, caption = nullptr;
    HFONT subtitle = nullptr;  // Fluent Title (28 px): page heading.
    HFONT rowTitle = nullptr;  // Fluent Body labels: 14 px, not bold.
    HFONT windowTitle = nullptr;  // Integrated title: Caption, with semibold emphasis.
    HFONT navigationIcons = nullptr;
    HFONT statusIcons = nullptr;  // 16 px Segoe Fluent Icons for InfoBar severity icons, or null.
    HFONT icons = nullptr;  // Segoe Fluent Icons / MDL2 (nullptr if neither is installed).
    HFONT chevrons = nullptr;  // 12 px icons: arrow of the dropdowns and the number boxes.
};

